from h34 import *
M=mcq;F=tf;S=short;N=num
def rope(name):
    b='<text x="380" y="22" text-anchor="middle" font-size="18" font-weight="bold">One metre, half a metre and a quarter metre</text>'
    for y,w,l in [(60,640,'1 metre'),(105,320,'half metre (fold the rope once)'),(150,160,'quarter metre (fold again)')]:
        b+=f'<rect x="40" y="{y}" width="{w}" height="16" rx="8" fill="#f4a261" stroke="#333" stroke-width="2"/><text x="{50+w}" y="{y+13}" font-size="15">{l}</text>'
    svgfile(name,760,190,b)
rope('c3-metre-rope.svg')
chapter(3,'maths','fun-at-class-party','Fun at Class Party',
 ('Getting ready for the class party','The children of Class 3 are getting ready for a party. They decorate the board with paper strings, measure a window and a table, and make costumes for a drama. They find out how to measure length with a hand span, a footstep, a pencil and a string and why a common unit is useful.'),
 [('Measuring with our own units',['We can measure length with parts of our body. A hand span, a footstep and an arm are body units that everyone has.','Leena and Adi measure the same table with their hand spans, but they may get different numbers, because their hands are of different sizes.','Paper strings, pencils and ropes can also be used as units. When two people use the same unit, they get the same count.','To say whether a string is longer or shorter, we put them side by side starting from the same point.','The shortest string is the one that ends first and the longest string ends last.']),
  ('Comparing without bringing things together',['Shelly and Adi want to know if a large table will pass through the door. They cannot lift the table, so they cut a thread as long as the table\'s breadth and check it against the door.','If a thread matches the length of something, we can carry the thread to the other object. A thread is a tool for comparing things that cannot be placed side by side.','If both the length and the breadth of a table are more than the width of the door, we may still be able to tilt it through the door, but if the table is too wide it cannot go through.','Comparing with a common unit, such as a thread, is called indirect measurement.']),
  ('The metre',['Small units such as a pencil are slow to measure a long thing like a saree. A paper strip double the size of a pencil helps, and longer strips help even more.','A shopkeeper measures cloth with a metre rod. A metre is a standard unit for length, and it is the same for everyone everywhere.','We can make a metre rope. We take a metre rod and a rope, make a knot at one end and another knot at one metre. The length between the knots is a metre.','Fold the rope in half to get half a metre and fold again to get a quarter metre. Four quarter metres make a metre and two half metres make a metre.','Many children are taller than one metre. Some things in a class are more than a metre long, some less and some about equal to a metre.']),
  ('Checking and estimating',['Is everyone\'s head 3 hand spans round, and is a forearm as long as a foot? We can measure and see that these are not exactly true for every child.','Before we measure, we estimate. After we measure with the metre rope, we see whose estimate was closest.','If we cut a metre rope into 4 equal pieces, we need to make 3 cuts. We can fit a number of footsteps in a metre, and it depends on the size of the feet.'])],
 [('Why do Leena and Adi get different numbers when they measure the same table with their hand spans?',[('Hand spans are different sizes.','Body units differ from person to person.'),('A bigger hand span covers more, so Adi counts fewer.','The count depends on the unit.'),('To get the same answer, both should use a standard unit, like a metre or a common strip.','Everyone then gets the same result.')]),
  ('How do you make a half-metre rope from a metre rope?',[('Fold the one-metre rope so that the two ends meet.','Make two equal parts.'),('Each part is half a metre.','Fold again to get quarter metres.'),('Two half-metre ropes make a metre.','Check against the metre rod.')]),
  ('A metre rope is cut into 4 equal pieces. How many cuts are needed?',[('Draw the rope and mark the pieces.','See how pieces are made.'),('To make 2 pieces we need 1 cut, for 3 pieces 2 cuts, for 4 pieces 3 cuts.','Pieces are one more than the cuts.'),('3 cuts are needed.','Each piece is a quarter metre.')])],
 ('Explain why we use a metre to measure instead of a hand span.',['Hand spans differ','A metre is the same for everyone','A metre helps in measuring long things','Compare with the same unit'],['Everyone has the same hand span','Metre is only for cloth']),
 ['We can measure length with a hand span, a footstep or a string, but body units differ from person to person.','Comparing with a thread or strip lets us measure indirectly.','A metre is a standard unit of length.','Half a metre and a quarter of a metre can be made by folding a metre rope.','We estimate first and then check by measuring.'],
 [M('1',1,'Which is a standard unit of length?','Metre',[('Hand span','A hand span differs from person to person'),('Footstep','Footsteps differ')],'A metre is the same for everyone.'),
  M('2',1,'Why might two children get different counts when they measure the same table with their hand spans?','Their hand spans are different sizes',[('The table changes','The table is the same'),('They counted wrongly','Both counted correctly')],'Body units differ.'),
  N('3',1,'How many half-metre pieces make a metre?',2,'Two halves make a whole.',[(4,'4 quarter metres make a metre'),(1,'One half metre is only half')]),
  N('4',1,'How many quarter-metre pieces make a metre?',4,'Four quarters make a whole.',[(2,'2 halves make a metre'),(8,'Check the quarter')]),
  M('5',2,'How do you find the shortest of three strings?','Place them side by side from the same start',[('Look at the colour','Colour does not tell the length'),('Weigh them','Weight does not tell the length')],'Start from the same point and see which ends first.'),
  M('6',2,'Why did Shelly and Adi use a thread for the table?','To compare the table with the door without lifting it',[('Because the thread is heavy','Weight is not involved'),('To decorate the door','It is for measuring')],'A thread carries the length to the door.'),
  N('7',2,'How many cuts make 4 equal pieces from one rope?',3,'3 cuts make 4 pieces.',[(4,'4 cuts make 5 pieces'),(2,'2 cuts make 3 pieces')]),
  F('8',2,'A metre is the same length for everyone.',True,'It is a standard unit.'),
  F('9',2,'Everyone\'s forearm is exactly as long as their foot.',False,'We can measure and see that it differs.'),
  M('10',2,'A rope is folded in half twice. What fraction of the rope is one part?','A quarter',[('A half','That is after one fold'),('A whole','The rope is cut')],'Half of a half is a quarter.'),
  S('11',3,'Name a standard unit for measuring cloth.',['metre','a metre','meter'],'Cloth is measured in metres.'),
  F('12',3,'If we estimate before measuring, we can check whose guess was closest.',True,'We compare the estimate with the real measure.')],
 svgs=[('c3-metre-rope','A metre rope, a half-metre rope and a quarter-metre rope','Folding the rope gives half and quarter metres.')],
 keep=['metre','hand span','estimate'])
